create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text default 'Pikachu Athlete', goal text default 'Stay Fit', height_cm numeric, weight_kg numeric, created_at timestamptz default now());
create table if not exists public.exercises (id bigint generated by default as identity primary key, name text unique not null, seconds int default 0, reps int default 0, muscle text, instructions text, animation_url text, video_url text, created_at timestamptz default now());
create table if not exists public.workouts (id bigint generated by default as identity primary key, name text unique not null, level text default 'Beginner', duration_minutes int default 20, calories int default 200, cover_url text, created_at timestamptz default now());
create table if not exists public.workout_exercises (workout_id bigint references public.workouts(id) on delete cascade, exercise_id bigint references public.exercises(id) on delete cascade, position int not null, primary key(workout_id, exercise_id));
create table if not exists public.workout_sessions (id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade not null, workout_id bigint references public.workouts(id), started_at timestamptz default now(), completed_at timestamptz, calories int default 0);
create table if not exists public.exercise_logs (id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade not null, exercise_id bigint references public.exercises(id), session_id bigint references public.workout_sessions(id) on delete cascade, completed_at timestamptz default now());
create table if not exists public.user_settings (user_id uuid primary key references auth.users(id) on delete cascade, reminders boolean default true, sound boolean default true, vibration boolean default true, metric boolean default true);
create table if not exists public.banners (id bigint generated by default as identity primary key, title text not null, subtitle text, image_url text, action text, active boolean default true, created_at timestamptz default now());

alter table public.profiles enable row level security; alter table public.workout_sessions enable row level security; alter table public.exercise_logs enable row level security; alter table public.user_settings enable row level security;
alter table public.exercises enable row level security; alter table public.workouts enable row level security; alter table public.workout_exercises enable row level security; alter table public.banners enable row level security;

drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id);
drop policy if exists sessions_self on public.workout_sessions; create policy sessions_self on public.workout_sessions for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists logs_self on public.exercise_logs; create policy logs_self on public.exercise_logs for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists settings_self on public.user_settings; create policy settings_self on public.user_settings for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists exercises_public on public.exercises; create policy exercises_public on public.exercises for select using (true);
drop policy if exists workouts_public on public.workouts; create policy workouts_public on public.workouts for select using (true);
drop policy if exists workout_exercises_public on public.workout_exercises; create policy workout_exercises_public on public.workout_exercises for select using (true);
drop policy if exists banners_public on public.banners; create policy banners_public on public.banners for select using (active=true);

